// 解码 Base64 为 Uint8Array
function base64ToUint8Array(base64) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// 构造单台服务器动态状态
function generateServerPayload(s, now) {
  // 随机呼吸抖动 (±15% 流量，±2% CPU)
  const jitterFactor = 0.85 + Math.random() * 0.3;
  const netIn = Math.round(s.baseNetIn * jitterFactor);
  const netOut = Math.round(s.baseNetOut * jitterFactor);
  const cpu = Math.max(1, Math.min(99, +(s.baseCpu + (Math.random() * 4 - 2)).toFixed(1)));
  const mem = Math.max(5, Math.min(95, +(s.baseMem + (Math.random() * 2 - 1)).toFixed(1)));
  const memUsed = Math.round(s.info.mem_total * (mem / 100));
  const diskUsed = Math.round(s.info.disk_total * 0.35);

  // 30 天在线时间轴 (全部 100% 满格绿条)
  const uptimeTimeline = [];
  for (let i = 29; i >= 0; i--) {
    uptimeTimeline.push({
      t: now - i * 86400000,
      status: "online",
      uptimePct: 100
    });
  }

  // 40 个历史指标点
  const history = [];
  for (let i = 39; i >= 0; i--) {
    const ptTime = Math.floor(now / 1000) - i * 3;
    const wave = Math.sin(ptTime / 20) * 0.15;
    history.push({
      time: ptTime,
      cpu: Math.max(1, +(cpu + wave * 5).toFixed(1)),
      mem: Math.max(10, +(mem + wave * 2).toFixed(1)),
      swap: 0,
      rx_speed: Math.round(netIn * (1 + wave)),
      tx_speed: Math.round(netOut * (1 + wave))
    });
  }

  // 流量统计
  const limitGB = s.trafficLimitGB || 0;
  let trafficStats;
  if (!limitGB) {
    trafficStats = {
      limitGB: 0,
      resetDay: 1,
      alertPercent: 80,
      cycleId: "2026-10-01",
      nextResetStr: "2026-11-01",
      daysRemaining: 2,
      usedBytes: 1982348123000,
      usedGB: 1846.2,
      remainingGB: 0,
      percent: 0,
      status: "unlimited",
      color: "slate",
      label: "不限流量"
    };
  } else {
    const usedGB = +(limitGB * 0.32).toFixed(1);
    const pct = Math.round((usedGB / limitGB) * 100);
    trafficStats = {
      limitGB: limitGB,
      resetDay: 1,
      alertPercent: 80,
      cycleId: "2026-10-01",
      nextResetStr: "2026-11-01",
      daysRemaining: 2,
      usedBytes: usedGB * 1073741824,
      usedGB: usedGB,
      remainingGB: +(limitGB - usedGB).toFixed(1),
      percent: pct,
      status: "normal",
      color: "emerald",
      label: `${usedGB} / ${limitGB} GB (${pct}%)`
    };
  }

  const cleanInfo = {
    ...s.info,
    disk_total: s.info.disk_total,
    unlocks: s.unlocks
  };

  const cleanMetrics = {
    cpu: cpu,
    memory: mem,
    memory_used: memUsed,
    swap: 0,
    swap_used: 0,
    disk: 35,
    disk_used: diskUsed,
    disk_percent: 35,
    net_in: netIn,
    net_out: netOut,
    net_total_in: Math.round(netIn * 12400),
    net_total_out: Math.round(netOut * 11800),
    load_1: +(cpu / 25).toFixed(2),
    load_5: +(cpu / 28).toFixed(2),
    load_15: +(cpu / 30).toFixed(2),
    tcp_count: 142 + Math.floor(Math.random() * 20),
    udp_count: 38 + Math.floor(Math.random() * 8),
    process_count: 98 + Math.floor(Math.random() * 5)
  };

  return {
    ...s,
    status: "online",
    last_seen: now,
    info: cleanInfo,
    metrics: cleanMetrics,
    history: history,
    uptimeTimeline: uptimeTimeline,
    uptimePercent: "100.0",
    traffic: trafficStats
  };
}

// 构造全量 Payload
function generateFullPayload() {
  const now = Date.now();
  let totalRx = 0;
  let totalTx = 0;

  const telemetryMap = {};
  const serversData = MOCK_SERVERS.map(s => {
    const srv = generateServerPayload(s, now);
    totalRx += srv.metrics.net_in;
    totalTx += srv.metrics.net_out;
    telemetryMap[s.id] = {
      status: srv.status,
      last_seen: srv.last_seen,
      info: srv.info,
      metrics: srv.metrics,
      history: srv.history,
      uptimeTimeline: srv.uptimeTimeline,
      uptimePercent: srv.uptimePercent,
      traffic: srv.traffic
    };
    return srv;
  }).sort((a, b) => a.order - b.order);

  return {
    timestamp: now,
    siteTitle: "Tanz Probe · 全球分布式云探针 (Live Demo)",
    siteSubtitle: "Cloudflare Workers 边缘无服务器驱动 · 60FPS 零频 GC 架构大屏",
    hideIpMode: "mask",
    theme: "paper",
    global: {
      totalServers: serversData.length,
      onlineServers: serversData.length,
      offlineServers: 0,
      netInSpeed: totalRx,
      netOutSpeed: totalTx,
      totalBandwidth: totalRx + totalTx,
      historicalPeak: 1987654321 // 1.85 GB/s
    },
    servers: serversData,
    telemetry: telemetryMap,
    pingTargets: MOCK_TARGETS,
    pingIntervalSec: 3,
    historicalPeak: 1987654321,
    services: [
      { name: "Cloudflare Edge (Anycast)", port: 443, status: "ok", latency: "6 ms" },
      { name: "HTTPS (Web 443)", port: 443, status: "ok", latency: "12 ms" },
      { name: "SSH (远程管理 22)", port: 22, status: "ok", latency: "14 ms" },
      { name: "WebSocket (边缘实时推流)", port: 5555, status: "ok", latency: "8 ms" }
    ],
    ssl: {
      issuer: "Let's Encrypt / Cloudflare Edge SSL",
      validTo: "2027-12-31",
      daysLeft: 420
    }
  };
}

// 构造 1h / 6h / 12h / 24h 节点指标历史
function generateNodeMetricsHistory(nodeId, range) {
  const now = Math.floor(Date.now() / 1000);
  let windowSec = 3600;
  if (range === '6h') windowSec = 6 * 3600;
  else if (range === '12h') windowSec = 12 * 3600;
  else if (range === '24h' || range === '1d') windowSec = 24 * 3600;

  const numBins = 40;
  const stepSec = Math.max(1, Math.floor(windowSec / numBins));
  const alignedNow = Math.floor(now / stepSec) * stepSec;
  const timeline = [];
  const labels = [];
  const cpuData = [];
  const memData = [];
  const swapData = [];

  const s = MOCK_SERVERS.find(x => x.id === nodeId) || MOCK_SERVERS[0];
  const baseCpu = s.baseCpu;
  const baseMem = s.baseMem;

  for (let i = numBins; i >= 0; i--) {
    const t = alignedNow - (i * stepSec);
    timeline.push(t);
    const d = new Date(t * 1000);
    labels.push(`${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}`);
    
    const noise = Math.sin(i * 0.6) * 3 + (Math.random() * 2 - 1);
    cpuData.push(Math.max(1, Math.min(95, +(baseCpu + noise).toFixed(1))));
    memData.push(Math.max(10, Math.min(90, +(baseMem + noise * 0.5).toFixed(1))));
    swapData.push(0);
  }

  return {
    ok: true,
    nodeId,
    range,
    timeline,
    labels,
    cpu: cpuData,
    mem: memData,
    swap: swapData,
    memTotalGB: Math.round(s.info.mem_total / (1024 * 1024 * 1024)),
    swapTotalGB: Math.round(s.info.swap_total / (1024 * 1024 * 1024)),
    current: {
      cpu: cpuData[cpuData.length - 1],
      mem: memData[memData.length - 1],
      swap: 0
    }
  };
}

// 构造节点对所有探测目标的时延历史
function generateNodeLatencyHistory(nodeId, range) {
  const now = Math.floor(Date.now() / 1000);
  let windowSec = 3600;
  if (range === '6h') windowSec = 6 * 3600;
  else if (range === '12h') windowSec = 12 * 3600;
  else if (range === '24h' || range === '1d') windowSec = 24 * 3600;

  const numBins = 30;
  const stepSec = Math.max(1, Math.floor(windowSec / numBins));
  const alignedNow = Math.floor(now / stepSec) * stepSec;
  const timeline = [];

  for (let i = numBins; i >= 0; i--) {
    timeline.push(alignedNow - (i * stepSec));
  }

  // 根据不同节点地理位置设置真实 RTT 均值
  let baseRtts = [8, 14, 28, 36, 12];
  if (nodeId === 'node-la') baseRtts = [135, 142, 155, 162, 148];
  else if (nodeId === 'node-de' || nodeId === 'node-uk') baseRtts = [145, 150, 168, 175, 160];
  else if (nodeId === 'node-jp') baseRtts = [28, 35, 48, 55, 38];

  const targetsData = MOCK_TARGETS.map((tgt, idx) => {
    const base = baseRtts[idx % baseRtts.length];
    const lats = timeline.map(t => {
      const r = base + Math.sin(t / 60) * 3 + (Math.random() * 2 - 1);
      return Math.max(1, Math.round(r));
    });
    const minVal = Math.min(...lats);
    const maxVal = Math.max(...lats);
    const avgVal = Math.round(lats.reduce((a, b) => a + b, 0) / lats.length);

    return {
      targetId: tgt.id,
      targetName: tgt.name,
      flag: tgt.flag,
      latencies: lats,
      stats: {
        min: minVal,
        max: maxVal,
        avg: avgVal,
        loss: 0
      }
    };
  });

  return {
    ok: true,
    nodeId,
    range,
    windowSec,
    timestamps: timeline,
    targets: targetsData
  };
}

